   443→// ChangePasswordHandler allows a logged-in user to change their password.
   444→// POST /api/user/change-password
   445→func (m *Manager) ChangePasswordHandler(w http.ResponseWriter, r *http.Request) {
   446→	if r.Method != http.MethodPost {
   447→		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
   448→		return
   449→	}
   450→
   451→	user, ok := GetUserFromContext(r.Context())
   452→	if !ok {
   453→		writeJSONError(w, "Unauthorized", http.StatusUnauthorized)
   454→		return
   455→	}
   456→
   457→	var req struct {
   458→		CurrentPassword string `json:"current_password"`
   459→		NewPassword     string `json:"new_password"`
   460→	}
   461→	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
   462→		writeJSONError(w, "Invalid request body", http.StatusBadRequest)
   463→		return
   464→	}
   465→
   466→	if req.CurrentPassword == "" || req.NewPassword == "" {
   467→		writeJSONError(w, "Current password and new password are required", http.StatusBadRequest)
   468→		return
   469→	}
   470→
   471→	if len(req.NewPassword) < 8 {
   472→		writeJSONError(w, "New password must be at least 8 characters", http.StatusBadRequest)
   473→		return
   474→	}
   475→
   476→	// Verify current password
   477→	if !VerifyPassword(user.PasswordHash, req.CurrentPassword) {
   478→		writeJSONError(w, "Current password is incorrect", http.StatusUnauthorized)
   479→		return
   480→	}
   481→
   482→	// Update password
   483→	if err := UpdateUserPassword(r.Context(), m.DB, m.DBDriver, user.ID, req.NewPassword); err != nil {
   484→		writeJSONError(w, "Failed to update password", http.StatusInternalServerError)
   485→		return
   486→	}
   487→
   488→	writeJSON(w, map[string]interface{}{
   489→		"success": true,
   490→		"message": "Password changed successfully",
   491→	}, http.StatusOK)
   492→}
   493→
   494→// Helper functions
   495→
   496→func writeJSON(w http.ResponseWriter, data interface{}, status int) {
   497→	w.Header().Set("Content-Type", "application/json")
   498→	w.WriteHeader(status)
   499→	json.NewEncoder(w).Encode(data)
   500→}
   501→
   502→func writeJSONError(w http.ResponseWriter, message string, status int) {
   503→	writeJSON(w, map[string]interface{}{
   504→		"error": message,
   505→	}, status)
   506→}
   507→
   508→func getClientIP(r *http.Request) string {
   509→	// Check X-Forwarded-For header first
   510→	forwarded := r.Header.Get("X-Forwarded-For")
   511→	if forwarded != "" {
   512→		return forwarded
   513→	}
   514→	// Fall back to RemoteAddr
   515→	return r.RemoteAddr
   516→}
