	var args []interface{}

	switch dbDriver {
	case "pgx", "duckdb":
		query = `SELECT COUNT(*) FROM users`
		if search != "" {
			query += `
			WHERE (
				email ILIKE $1 OR
				COALESCE(username, '') ILIKE $1 OR
				COALESCE(external_id, '') ILIKE $1 OR
