			--th-bg: #424242;
			--hover-bg: #f9f9f9;
		}
		@media (prefers-color-scheme: dark) {
			:root {
				--bg-primary: #1a1a1a;
				--bg-card: #2b2b2b;
				--text-primary: #eee;
				--text-secondary: #aaa;
				--text-muted: #777;
				--border-color: #444;
