}

.copy-btn {
  padding: 4px 10px;
  background: var(--primary-color);
  border: none;
  border-radius: 4px;
  color: white;
  cursor: pointer;
  font-size: 12px;
}

.copy-btn:hover { opacity: 0.85; }

.badge {
  display: inline-block;
  padding: 2px 8px;
  border-radius: 4px;
  font-size: 12px;
  font-weight: 600;
}

.badge-green { background: #2e7d32; color: white; }
.badge-orange { background: #e65100; color: white; }
.badge-blue { background: #1565c0; color: white; }

/* Uploads table - Admin style */
.summary {
  background: var(--bg-card);
  padding: 15px;
  margin-bottom: 20px;
  border-radius: 5px;
  font-size: 0.9em;
  color: var(--text-secondary);
  display: flex;
  flex-wrap: wrap;
  gap: 15px;
  align-items: center;
}

.summary strong { color: var(--text-primary); }

.summary select, .summary input {
  padding: 4px 8px;
  border-radius: 4px;
  border: 1px solid var(--border-color);
  background: var(--bg-card);
  color: var(--text-primary);
}

.page-btn {
  display: inline-block;
  padding: 6px 12px;
  margin: 0 2px;
  border: 1px solid var(--border-color);
  border-radius: 4px;
  background: var(--bg-card);
  color: var(--link-color);
  text-decoration: none;
  font-size: 0.9em;
  cursor: pointer;
}

.page-btn:hover { background: var(--hover-bg); }
.page-btn.active { background: var(--link-color); color: white; font-weight: bold; }
.page-btn.disabled { color: var(--text-muted); cursor: not-allowed; }

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
  background: var(--bg-card);
}

th {
  text-align: left;
  padding: 12px;
  background: var(--th-bg);
  color: white;
  font-weight: 600;
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  position: sticky;
  top: 0;
  z-index: 10;
}

td {
  padding: 10px 12px;
  border-bottom: 1px solid var(--border-color);
  color: var(--text-primary);
}

tr:hover td { background: var(--hover-bg); }

